import weakref

class EventListener:
    def __init__(self, func):
        self.func = func

    def __call__(self, *args, **kwargs):
        return self.func(*args, **kwargs)

class ConnectionPool:
    def __init__(self, max_connections):
        self.max_connections = max_connections
        self.available_connections = []
        self.in_use_connections = set()
        self.event_listeners = []

    def add_event_listener(self, listener_func):
        self.event_listeners.append(EventListener(listener_func))

    def notify_listeners(self, event_type, *args, **kwargs):
        for listener in self.event_listeners:
            if hasattr(listener, f'on_{event_type}'):
                getattr(listener, f'on_{event_type}')(*args, **kwargs)

    def acquire(self):
        if len(self.available_connections) > 0:
            conn = self.available_connections.pop()
            self.in_use_connections.add(conn)
            self.notify_listeners('acquire', conn)
            return conn
        else:
            raise Exception("No available connections")

    def release(self, conn):
        self.in_use_connections.remove(conn)
        self.available_connections.append(conn)
        self.notify_listeners('release', conn)

    def close(self):
        while len(self.available_connections) > 0:
            conn = self.available_connections.pop()
            self.in_use_connections.remove(conn)
            conn.close()
            self.notify_listeners('close', conn)
```

This implementation ensures that connections are properly managed and event listeners are notified when connections are acquired, released, or closed. The `EventListener` class is used to wrap functions so they can be weakly referenced without causing a memory leak.

