import time
from threading import Thread, Lock
from queue import Queue

class DistributedLock:
    def __init__(self, name, lease_time=60):
        self.name = name
        self.lease_time = lease_time
        self.lock = Lock()
        self.is_locked = False
        self.expiry_time = None

    def acquire(self):
        with self.lock:
            if not self.is_locked:
                self.is_locked = True
                self.expiry_time = time.time() + self.lease_time
                print(f"Lock acquired by {self.name} at {time.time()}")

    def release(self):
        with self.lock:
            if self.is_locked:
                self.is_locked = False
                self.expiry_time = None
                print(f"Lock released by {self.name} at {time.time()}")

    def is_expired(self):
        return self.expiry_time is not None and time.time() > self.expiry_time

class HeartbeatDaemon(Thread):
    def __init__(self, lock, heartbeat_queue):
        super().__init__()
        self.lock = lock
        self.heartbeat_queue = heartbeat_queue
        self.running = True

    def run(self):
        while self.running:
            if self.lock.is_expired():
                print(f"{self.lock.name} lock expired at {time.time()}")
                self.heartbeat_queue.put((self.lock.name, 'release'))
            else:
                print(f"Sending heartbeat for {self.lock.name} at {time.time()}")
                self.heartbeat_queue.put((self.lock.name, 'acquire'))
            time.sleep(1)

    def stop(self):
        self.running = False

# Example usage
if __name__ == "__main__":
    lock = DistributedLock('example_lock')
    heartbeat_queue = Queue()

    daemon = HeartbeatDaemon(lock, heartbeat_queue)
    daemon.start()

    # Simulate lock acquisition and release
    lock.acquire()
    time.sleep(5)  # Simulate some work
    lock.release()

    # Stop the daemon after some time
    time.sleep(10)
    daemon.stop()
